INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Fallunterscheidung dasselbe wie eine Schleife?', 2, '[{"text": "Nein", "correct": true, "because": "Entscheidung vs. Wiederholung"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Funktionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt eine Fallunterscheidung?', 3, '[{"text": "Bedingte Codeausführung", "correct": true, "because": "Entscheidungen treffen"}, {"text": "Daten wiederholen", "correct": false, "because": "Schleifenfunktion"}, {"text": "Daten speichern", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Strukturen gehören zur Fallunterscheidung?', 5, '[{"text": "if-Anweisung", "correct": true, "because": "Einfache Bedingung"}, {"text": "switch-Anweisung", "correct": true, "because": "Mehrere Fälle"}, {"text": "while-Schleife", "correct": false, "because": "Wiederholung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Fallunterscheidungen prüfen Bedingungen. b) Sie führen immer alle Fälle aus.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nur ein Fall"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer Fallunterscheidung?', 4, '[{"text": "Bedingungen", "correct": false, "because": "Entscheidungsgrundlage"}, {"text": "Codeblöcke", "correct": false, "because": "Ausführungsteil"}, {"text": "Papierformat", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Fallunterscheidung mehrere Bedingungen haben kann?', 2, '[{"text": "Ja", "correct": true, "because": "if-else-if"}, {"text": "Nein", "correct": false, "because": "Mehrere möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anweisung ist eine einfache Fallunterscheidung?', 3, '[{"text": "if", "correct": true, "because": "Ein Fall"}, {"text": "for", "correct": false, "because": "Schleife"}, {"text": "while", "correct": false, "because": "Wiederholung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Fallunterscheidung?', 5, '[{"text": "Flexibilität", "correct": true, "because": "Verschiedene Fälle"}, {"text": "Klarheit", "correct": true, "because": "Übersichtliche Logik"}, {"text": "Speicherkapazität", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Fallunterscheidungen steuern Programmfluss. b) Sie sind nur für Schleifen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Keine Schleifen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Fallunterscheidung?', 4, '[{"text": "Bedingung", "correct": false, "because": "Entscheidungsgrundlage"}, {"text": "Codeblock", "correct": false, "because": "Ausführung"}, {"text": "Schleifenstruktur", "correct": true, "because": "Keine Wiederholung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Fallunterscheidung immer zweiseitig?', 2, '[{"text": "Nein", "correct": true, "because": "Einseitig möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Programmiersprachen nutzen Fallunterscheidungen?', 4, '[{"text": "Java", "correct": true, "because": "if, switch"}, {"text": "Python", "correct": true, "because": "if-elif"}, {"text": "HTML", "correct": false, "because": "Keine Logik"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Fallunterscheidungen nur für einfache Programme sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch komplexe Logik"}, {"text": "Ja", "correct": false, "because": "Breit einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer Fallunterscheidung?', 3, '[{"text": "Klare Bedingungen", "correct": true, "because": "Entscheidung treffen"}, {"text": "Farben", "correct": false, "because": "Irrelevant"}, {"text": "Schnelligkeit", "correct": false, "because": "Korrektheit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Fallunterscheidungen können verschachtelt sein. b) Sie wiederholen Code automatisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Keine Wiederholung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Darstellungen zeigen eine Fallunterscheidung?', 5, '[{"text": "Flussdiagramm", "correct": true, "because": "Entscheidungspfade"}, {"text": "Struktogramm", "correct": true, "because": "If-else"}, {"text": "Papierformular", "correct": false, "because": "Nicht technisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Fallunterscheidung unwichtig?', 3, '[{"text": "Bedingungslogik", "correct": false, "because": "Entscheidung"}, {"text": "Ausführungspfade", "correct": false, "because": "Ergebnisse"}, {"text": "Schriftart", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann eine Fallunterscheidung mehrere Fälle haben?', 3, '[{"text": "Ja", "correct": true, "because": "Switch oder if-else-if"}, {"text": "Nein", "correct": false, "because": "Mehrere möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Fallunterscheidung immer ausgeführt wird?', 2, '[{"text": "Nein", "correct": true, "because": "Bedingungsabhängig"}, {"text": "Ja", "correct": false, "because": "Nur bei Erfüllung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für eine Fallunterscheidung zentral?', 4, '[{"text": "Bedingungen", "correct": true, "because": "Entscheidungsgrundlage"}, {"text": "Wiederholungen", "correct": false, "because": "Schleifen"}, {"text": "Papierdokumente", "correct": false, "because": "Irrelevant"}]');
